from pathlib import Path
import html, json

ROOT=Path(__file__).parent
sources={
'jev':('TypeSafe AI, Jev documentation','https://docs.typesafe.ai/introduction'),
'do':('DigitalOcean, System One API','https://docs.digitalocean.com/products/inference/how-to/use-system-one-api/'),
'boe':('Bank of England / FCA, 2024 AI survey','https://www.bankofengland.co.uk/report/2024/artificial-intelligence-in-uk-financial-services-2024'),
'dbs':('DBS, corporate credit memo rollout, 19 Aug 2026','https://www.dbs.com/newsroom/DBS_scales_agentic_AI_to_transform_way_of_working_for_corporate_bankers_freeing_up_time_for_more_strategic_client_engagements'),
'nist':('NIST, Generative AI Profile, July 2024','https://www.nist.gov/publications/artificial-intelligence-risk-management-framework-generative-artificial-intelligence'),
'cal':('Guo et al., On Calibration of Modern Neural Networks, ICML 2017','https://proceedings.mlr.press/v70/guo17a.html'),
'mas':('MAS, proposed AI risk guidelines, 13 Nov 2025','https://www.mas.gov.sg/news/media-releases/2025/mas-guidelines-for-artificial-intelligence-risk-management')}
slides=[]
def add(title,body,notes='',refs=(),kind=''):
    slides.append(dict(title=title,body=body,notes=notes,refs=refs,kind=kind))
def rows(headers,data):
    return '<table><thead><tr>'+''.join('<th>'+v+'</th>' for v in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+v+'</td>' for v in r)+'</tr>' for r in data)+'</tbody></table>'
def split(a,b):return '<div class="split"><div>'+a+'</div><div>'+b+'</div></div>'
def points(items):return '<ul>'+''.join('<li>'+x+'</li>' for x in items)+'</ul>'

add('A banking decision model<br>for agentic workflows', '<p class="hero">A Jev-inspired approach to bounded automation</p><p class="sub">Business case, model development and control architecture</p><p class="meta">Discussion draft · 29 September 2026</p>', 'Working assumption: an internal business and IT audience deciding whether to fund a pilot. “Jev-like” means typed, probabilistic judgments embedded in software. Geography, sponsor, budget and deployment constraints await confirmation. This is a proposed design, not a tested model or a claim to reproduce Jev’s proprietary training.',kind='cover')
add('The proposal', split('<p class="statement">Build a reusable decision service for narrow banking judgments.</p>',points(['Identify customer intent and evidence gaps.','Return allowed labels and probabilities.','Let bank policy determine routing and permissions.','Escalate uncertain or consequential cases.']))+'<p class="callout">First investment: a service-triage pilot with measurable routing quality and handling time.</p>', 'The business objective is less avoidable manual triage without more missed urgent cases. IT owns a versioned service contract and operational controls. The pilot should compare buying a decision API with adapting a bank-hosted classifier before any commitment to a new foundation model.')
add('Adoption is broad. Full autonomy remains limited.', '<div class="metrics"><div><strong>75%</strong><p>of responding UK financial firms used AI</p></div><div><strong>2%</strong><p>of reported AI use cases had fully autonomous decisions</p></div></div><p class="sub">Bank of England / FCA survey, 2024. These figures cover AI broadly, not agentic banking adoption.</p><p class="callout">DBS reported rolling out agents for credit-memo preparation to about 1,500 employees in August 2026.</p>', 'These are different evidence types and populations. The survey is historical and self-reported. DBS is a bank-reported deployment example: agents prepare drafts, while bankers and risk managers deepen the assessment. Neither source establishes the performance or ROI of our proposed classifier.',('boe','dbs'))
add('What “Jev-like” means',rows(['Primitive','Banking question','Result consumed by software'],[['Choice','Which service queue fits this request?','Allowed label + distribution over labels'],['Score','How complete is the evidence against a rubric?','Distribution over ordered levels'],['Noul / binary','Does the text indicate suspected fraud?','Probability for a yes/no proposition']])+'<p class="callout">A probability describes a model judgment. Bank policy grants authority to act.</p>', 'Jev documentation describes state plus typed questions and composable judgments. This proposal borrows the interface and operating pattern. A conventional classifier can implement a similar contract without reproducing Jev architecture. A bank must test calibration on its own target population. A completeness score is not a credit risk score.',('jev','do'))
add('Different components do different jobs',rows(['Component','Useful role','Boundary'],[['Rules and policy engine','Enforce entitlements, limits and mandatory approvals','Explicit, versioned bank policy'],['Decision model','Interpret ambiguous text and assign bounded labels','Can abstain, misclassify or drift'],['Reasoning / language model','Plan a workflow, retrieve context and draft explanations','Generated content needs evidence checks'],['Workflow and tool gateway','Execute approved operations and reconcile outcomes','Authentication, idempotency and audit']]),'Use deterministic rules where the decision is already explicit. Introduce a model where language or context makes rule maintenance difficult. The decision model complements an agent, but a complex planning task may still need a reasoning model. No component should infer customer authentication from conversational confidence.')
add('The first use case: service-request triage',split('<p class="quote">“I don’t recognise this card payment, and my rent is due tomorrow.”</p><p>One message can contain several signals.</p>',points(['Primary intent: disputed card transaction.','Urgency and vulnerability: assess separately.','Missing evidence: verified transaction details.','Policy outcome: route to an authorised specialist.'])))
add('The use-case portfolio',rows(['Use case','Business measure','Initial authority'],[['Service triage · pilot','Routing accuracy, urgent-case recall, handling time','Recommend queue, then limited automatic routing'],['KYC evidence completeness','Rework and evidence collection time','Flag missing items for review'],['Credit-memo evidence checks','Unsupported claims and review time','Assist the credit reviewer'],['Payment / lending decisions','Loss, customer harm and decision quality','Outside initial autonomous scope']])+'<p class="sub">Proposed sequence. Local workflow volume, risk and data availability determine priority.</p>', 'KYC completeness does not establish identity or replace due diligence. Credit document checking does not approve credit. Payment authority and lending decisions require their own business, legal and validation case. Prioritisation should reward repeatable judgments and clear labels, not just theoretical cost savings.')
add('The control path',rows(['Stage','What happens','Accountable component'],[['1. Context','Authenticate caller, minimise data, fetch permitted evidence','Identity and data services'],['2. Judgment','Classify intent and independent risk signals','Versioned decision model'],['3. Policy','Apply permissions, thresholds and mandatory escalation','Bank policy engine'],['4. Action','Route case or request human approval','Workflow and tool gateway'],['5. Evidence','Record versions, inputs, outcome and overrides','Audit and monitoring']])+'<p class="callout">Every tool call passes through policy checks, including calls proposed by a reasoning agent.</p>', 'Proposed logical architecture. The model has no direct core banking credentials. Keep untrusted customer text separate from policy and system instructions. Restrict tools by principal and workflow state. Store sensitive evidence under bank retention and access rules. Use fail-closed behaviour for policy failure and route unavailable model cases to an existing manual queue.')
add('One judgment, one explicit contract',split('<pre>{\n  "intent": {\n    "card_dispute": 0.86,\n    "payment_status": 0.10,\n    "other": 0.04\n  },\n  "suspected_fraud": 0.72,\n  "missing_evidence": true\n}</pre>','<p class="eyebrow">Illustrative output, not a test result</p>'+points(['Separate mutually exclusive intent labels from independent flags.','Include unknown and out-of-scope outcomes.','Attach model, question, taxonomy and calibration versions.','Validate the response before policy evaluation.'])),'This is an illustrative bank-owned adapter contract, not a verbatim Jev API response. The missing-evidence Boolean can come from deterministic required-field checks. Probabilities for exclusive intent labels sum to one, while independent flags need not. Preserve raw responses for governed diagnostics when retention permits. Model-provided explanation text is not a substitute for a traceable evidence reference.')
add('Probability needs validation before automation',split('<p class="statement">Among comparable cases scored near 0.8, about 80% should satisfy the predicted event.</p>','<h3>Bank validation</h3>'+points(['Measure calibration on untouched, representative cases.','Check language, product and customer segments.','Measure error versus automation coverage.','Recheck after model or population changes.'])), 'Calibration is an aggregate statistical property, not a guarantee for an individual case. A high confidence score cannot establish authorisation or eliminate correlated errors. Guo et al. show that modern neural networks can be poorly calibrated and evaluate temperature scaling. Post-hoc calibration must use held-out data, with final evaluation on a separate test set. A binary probability and a vendor confidence field need not have the same semantics.',('cal',))
add('Thresholds follow the cost of mistakes',rows(['Decision','Primary concern','Proposed policy'],[['Suspected fraud signal','Missing a genuine urgent case','Tune recall and escalate ambiguous cases'],['Routine queue assignment','Avoidable transfer and rework','Automate only in validated segments'],['Missing required evidence','Proceeding with an incomplete record','Enforce explicit evidence checks'],['A money-moving action','Unauthorised or incorrect execution','Require independent bank controls and approvals']])+'<p class="callout">Choose thresholds on validation data. Release only after the risk owner accepts measured residual error.</p>','There is no universal safe cutoff such as 0.95. Choose operating points using error costs, uncertainty bounds, service capacity and the bank’s risk appetite. Abstention routes cases to a staffed process, not an unowned backlog. High recall is meaningful only with precision, volume and reviewer capacity alongside it.')
add('A model development path with decision gates',rows(['Stage','Work product','Gate'],[['Baseline','Rules, conventional classifier, structured-output LLM and Jev-style API comparison','Same cases, metrics and end-to-end costs'],['Adapt','Task heads or fine-tuning on approved bank labels','Improvement on held-out segments'],['Calibrate','Probability calibration and abstention policy','Acceptable error at useful coverage'],['Harden','Load, adversarial, privacy and failure testing','Independent release approval']])+'<p class="sub">Foundation-model training becomes a separate investment only if these paths leave a material gap.</p>', 'Proposed approach, not a description of proprietary Jev training. For fixed labels, a text encoder with classification heads is a candidate. A broader state-plus-question model may use an adaptable pretrained model with supervised decision training. Evaluate architecture choices rather than assuming that a small model or reinforcement learning is necessary. Synthetic or teacher-generated labels can augment training but should not define the final benchmark.')
add('The data advantage comes from adjudicated decisions',split('<h3>Training evidence</h3>'+points(['Historical cases with authorised data use.','Clear label definitions and policy versions.','Two reviewers for ambiguous or high-risk cases.','Explicit disagreements and “insufficient evidence”.']),'<h3>Evaluation protection</h3>'+points(['Split by time and customer or case family.','Keep duplicates and related cases together.','Hold out rare intents and difficult language.','Reserve a locked test set for release decisions.'])),'Do not treat past staff actions as perfect ground truth. They can encode inconsistent policy and unequal treatment. Build a label guide and adjudicate disagreements. Sensitive attributes may be needed for controlled fairness evaluation where legally permitted, but should not casually become model inputs. Dataset size follows class frequency, learning curves and the precision needed for the release claim.')
add('The release scorecard',rows(['Dimension','Evidence required'],[['Decision quality','Per-class precision and recall, confusion matrix, urgent-case misses'],['Probability quality','Brier score or log loss, reliability plots and subgroup calibration'],['Automation safety','Error among automated cases, abstention rate, override outcomes'],['Operational reliability','End-to-end p95 latency, timeouts, throughput and recovery'],['Economics','Cost per correctly completed case, rework and reviewer load']])+'<p class="sub">Targets and confidence bounds require agreement before testing. Aggregate accuracy alone is insufficient.</p>','Compare candidates on the same frozen dataset and workflow. Repeated stable outputs do not prove correctness or calibration. Include schema failure, empty output, prompt injection and distribution shift. For rare harmful errors, report sample size and uncertainty bounds instead of declaring safety from zero observed failures. Validation should be independent of the team selecting the model.')
add('The business case depends on workflow savings', '<p class="eyebrow">Illustrative monthly scenario · USD · not a forecast</p>'+rows(['Input','Assumption'],[['Eligible volume and successful automated share','100,000 cases × 40%'],['Net staff time released per automated case','3 minutes at $30 per hour'],['Gross capacity value','$60,000 per month'],['Recurring model, platform, review and operations cost','$20,000 per month'],['Net capacity value before build cost and losses','$40,000 per month']])+'<p class="callout">Capacity value becomes cash savings only when the operating model realises it.</p>','Arithmetic: 100,000 × 0.40 × 3/60 × $30 = $60,000. Net = $60,000 − $20,000. At 20% share, net is $10,000; at 60%, $70,000, holding other assumptions fixed. Break-even share is 13.3% before build costs and losses. Rework and exception handling must be included in net minutes or operating costs without double counting. Exclude speculative avoided fraud losses. Add one-time data, integration and validation investment to the actual approval case.')
add('Operating accountability',rows(['Owner','Accountability'],[['Business process owner','Customer outcome, workload, benefits and escalation staffing'],['Model team','Data lineage, model versions, monitoring and remediation'],['IT and security','Access boundaries, deployment, resilience and incident response'],['Risk / compliance / independent validation','Challenge the evidence and approve use within local policy'],['Audit','Review traceability and control operation']])+'<p class="sub">NIST offers a voluntary risk framework. Jurisdiction-specific banking requirements need a local mapping.</p>','Proposed operating model. NIST AI 600-1 is a voluntary cross-sectoral profile, not a bank authorisation or certification. The November 2025 MAS source is a consultation announcement and should not be presented as final binding requirements. Determine applicable local law, outsourcing, model governance, recordkeeping and customer protection obligations with the bank’s control functions.',('nist','mas'))
add('A gated 90-day pilot',rows(['Timing¹','Deliverable','Decision'],[['Days 1–20','Workflow baseline, labels, approved data and risk boundaries','Is the problem measurable?'],['Days 21–45','Candidate comparison and independent validation plan','Does a candidate beat the baseline?'],['Days 46–70','Shadow run with staff, no autonomous customer action','Do real cases confirm the result?'],['Days 71–90','Limited routing trial with rollback and monitoring','Expand, revise or stop']])+'<p class="sub">¹ Planning assumption. Data approval, integration and validation can extend the schedule.</p>','Suggested exit gates: approved data and labels; agreed minimum performance and uncertainty bounds; stable shadow results with a viable manual fallback; then limited routing only after control sign-off. Pause on increased urgent-case misses, unexplained subgroup deterioration, broken access controls or queue overload. Set numerical triggers with the risk and process owners before the trial.')
add('The decision for business and IT',split('<p class="statement">Fund a bounded pilot and a model comparison.</p>','<h3>Agree before kickoff</h3>'+points(['One process owner and one IT owner.','One workflow with an existing manual fallback.','Approved data access and an evaluation set.','A budget cap and explicit release criteria.']))+'<p class="callout">Scale only after measured gains survive the bank’s validation and control process.</p>','This is the proposed ask, pending confirmation of the deck’s actual purpose. If the audience is a customer or investor, rewrite this page as a product and commercial proposition. If the goal is an internal model-building programme, add named team capacity, architecture constraints, build costs and ownership of training data.')
add('Appendix: build, adapt or buy',rows(['Option','Strongest reason to choose it','Evidence still needed'],[['Buy decision API','Fast access to a typed decision capability','Bank benchmark, data handling, residency, SLA and exit terms'],['Adapt an available model','Control deployment and domain training','Licensing, hosting cost, calibration and maintenance capacity'],['Train a new foundation model','Distinct capability unavailable elsewhere','Sustained research advantage, lawful data and investment case']])+'<p class="sub">Working recommendation: benchmark buy and adapt in parallel before committing to foundation-model training.</p>','No vendor selection is implied. On-premise or private deployment availability for Jev has not been verified. Do not promise deployment modes, banking certifications or security guarantees without vendor evidence. The model interface can remain bank-owned to reduce switching costs.')
add('Appendix: failure and recovery',rows(['Failure','Control response'],[['Model outage or malformed result','Route to existing manual queue and record failure'],['Prompt injection in a customer document','Treat text as evidence, isolate instructions and restrict tools'],['High confidence but wrong judgment','Monitor outcome samples, overrides and drift; suspend affected segment'],['Duplicate or partially completed action','Use idempotency keys, transaction checks and reconciliation'],['Reviewer overload','Cap automation intake and route to a staffed contingency process']]),'These are proposed controls and test scenarios, not demonstrated guarantees. A classifier alone is not a reliable security perimeter against prompt injection. Test the complete agent, gateway and workflow. For actions without clean rollback, prevention and approval are essential. Maintain an incident owner, kill switch and a rehearsed manual continuity process.')
add('Appendix: evidence and open questions','<div class="sources">'+''.join('<p><a href="'+u+'" target="_blank" rel="noopener">'+html.escape(t)+'</a></p>' for t,u in sources.values())+'</div><p class="sub">Open: institution and jurisdiction, business objective, first workflow, hosting constraints, data readiness, budget and target presentation length.</p>', 'Sources reviewed 29 September 2026. Vendor documentation supports interface descriptions, not independent banking performance. Bank announcements describe reported deployments. All architecture, pilot gates, priorities and business-case assumptions in this deck are proposals. No model was trained or evaluated for this deck.')

exec((ROOT/'intro.py').read_text())
exec((ROOT/'visuals.py').read_text())

css='''*{box-sizing:border-box} :root{color-scheme:light;--ink:#112535;--muted:#52616c;--accent:#006e75;--line:#cbd6da;--paper:#f9fbfc}body{margin:0;background:#dce4e8;color:var(--ink);font-family:Arial,Helvetica,sans-serif}button,select{font:inherit}nav{position:fixed;z-index:10;bottom:18px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:10px;padding:8px 12px;background:#112535;color:white;border-radius:8px;box-shadow:0 4px 25px #0003}button,select{border:1px solid #64808e;background:transparent;color:inherit;border-radius:4px;padding:8px 12px;cursor:pointer}select{max-width:320px;background:#112535}button:disabled{opacity:.35;cursor:default}button:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #e7b050;outline-offset:3px}main{padding:34px 30px 100px}.slide{display:none;background:var(--paper);width:min(1280px,100%);min-height:720px;margin:auto;padding:52px 64px 46px;position:relative;border-top:8px solid var(--accent)}.slide.active{display:flex;flex-direction:column}.slide h2{font-size:42px;line-height:1.13;letter-spacing:-1.2px;margin:0 0 34px;max-width:1100px}.content{flex:1}.slide p,.slide li{font-size:24px;line-height:1.42}.slide p{margin:0 0 20px}.slide .sub{font-size:19px;color:var(--muted);line-height:1.45;margin-top:22px}.slide .eyebrow,.slide .meta{font-size:17px;letter-spacing:.8px;color:var(--muted)}.split{display:grid;grid-template-columns:1fr 1fr;gap:58px;align-items:start}.split>div+div{border-left:1px solid var(--line);padding-left:40px}.slide .statement{font-size:36px;line-height:1.28;letter-spacing:-.6px}.slide .quote{font-size:36px;line-height:1.3;color:var(--accent)}ul{padding-left:25px;margin:0}li{padding-left:5px;margin-bottom:18px}h3{font-size:25px;margin:0 0 20px}.callout{border-top:3px solid var(--accent);padding-top:20px;margin-top:28px!important;font-weight:600}table{border-collapse:collapse;width:100%;table-layout:fixed;font-size:21px;line-height:1.35}th{text-align:left;color:var(--accent);font-size:17px;font-weight:700;border-bottom:2px solid var(--accent);padding:0 18px 13px 0}td{padding:17px 20px 17px 0;border-bottom:1px solid var(--line);vertical-align:top}td:first-child{font-weight:600}tr:last-child td{border-bottom:0}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:75px}.metrics strong{font-size:108px;font-weight:600;letter-spacing:-7px;color:var(--accent)}.metrics p{max-width:380px}pre{font:21px/1.55 ui-monospace,SFMono-Regular,Consolas,monospace;white-space:pre-wrap;margin:0;color:var(--accent)}footer{margin-top:26px;display:flex;justify-content:space-between;align-items:end;gap:28px;font-size:13px;color:var(--muted)}footer a{color:var(--muted)}.cover{background:#102b3a;color:#fff;justify-content:center;border-color:#3ac1b0}.cover h2{font-size:64px;line-height:1.06;max-width:1000px;letter-spacing:-2px;margin:45px 0 30px}.cover .content{flex:0}.cover .hero{font-size:32px;color:#77ddd0}.cover .sub,.cover .meta,.cover footer{color:#c3d2d9}.cover .meta{margin-top:85px}.cover footer{margin-top:auto}.sources p{font-size:20px;margin:0 0 14px}.sources a{color:var(--accent)}aside{display:none;width:min(1280px,100%);margin:12px auto;background:white;padding:24px 40px;font-size:18px;line-height:1.6}body.notes aside.active{display:block}.count{white-space:nowrap;min-width:56px;text-align:center}.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}@media(max-width:800px){main{padding:12px 12px 120px}.slide{padding:28px 24px;min-height:calc(100vh - 140px)}.slide h2{font-size:32px}.cover h2{font-size:43px}.slide p,.slide li{font-size:20px}.slide .statement,.slide .quote{font-size:27px}.split{grid-template-columns:1fr;gap:24px}.split>div+div{padding-left:0;border-left:0;border-top:1px solid var(--line);padding-top:22px}table{font-size:16px}td{padding:12px 10px 12px 0}th{font-size:14px}.metrics{gap:20px}.metrics strong{font-size:76px}nav{width:calc(100% - 24px);flex-wrap:wrap;justify-content:center;bottom:8px;gap:6px}select{max-width:220px}footer{font-size:12px}.cover .meta{margin-top:35px}}@media print{@page{size:13.333in 7.5in;margin:0}body,main{background:white;padding:0;margin:0}nav,aside{display:none!important}.slide,.slide.active{display:flex!important;flex-direction:column;width:13.333in;height:7.5in;min-height:0;padding:38px 52px 30px;break-after:page;page-break-after:always;overflow:hidden;print-color-adjust:exact;-webkit-print-color-adjust:exact}.slide h2{font-size:36px;margin-bottom:24px}.slide p,.slide li{font-size:21px}table{font-size:19px}td{padding-top:13px;padding-bottom:13px}.cover h2{font-size:58px}.slide .statement,.slide .quote{font-size:31px}.slide .sub{font-size:17px}.cover .meta{margin-top:60px}.sources p{font-size:19px}.slide:last-of-type{break-after:auto}}'''
css+='''
.diagram{display:block;width:100%;height:auto;max-height:440px;overflow:visible}.slide .visual-caption{font-size:22px;line-height:1.4;margin-top:12px;max-width:1050px;color:var(--muted)}.visual h2{margin-bottom:22px}.visual footer{margin-top:20px}.visual footer a{font-size:12px}@media print{.diagram{max-height:405px}.slide .visual-caption{font-size:20px}.visual h2{margin-bottom:12px}}@media(max-width:800px){.visual .content{overflow-x:auto}.diagram{min-width:760px}.slide .visual-caption{font-size:19px}.visual .content:before{content:'Diagram: scroll horizontally on a small screen';display:block;font-size:13px;color:var(--muted);margin-bottom:14px}}
'''
out=['<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="A Jev-inspired banking decision model: business case, architecture, validation and pilot proposal."><title>Jev and Classifiers in Agentic Banking</title><style>'+css+'</style></head><body><main>']
for i,s in enumerate(slides):
    refs=' · '.join('<a href="'+sources[k][1]+'" target="_blank" rel="noopener">'+html.escape(sources[k][0])+'</a>' for k in s['refs'])
    out.append(f'<section class="slide {s["kind"]} {"active" if i==0 else ""}" id="slide-{i+1}" aria-label="Slide {i+1}"><h2>{s["title"]}</h2><div class="content">{s["body"]}</div><footer><span>{refs or "Agentic banking · introductory session"}</span><span>{i+1:02d} / {len(slides):02d}</span></footer></section><aside class="{"active" if i==0 else ""}"><strong>Presenter notes</strong><br>{html.escape(s["notes"] or "Illustrative workflow. Confirm routing and escalation rules with the bank process owner.")}</aside>')
out.append('</main><nav aria-label="Presentation controls"><button id="prev" aria-label="Previous slide">←</button><span class="count" aria-live="polite"></span><button id="next" aria-label="Next slide">→</button><select id="jump" aria-label="Choose slide">'+''.join(f'<option value="{i}">{i+1}. {html.escape(s["title"].replace("<br>"," "))}</option>' for i,s in enumerate(slides))+'</select><button id="notes" aria-pressed="false">Notes</button><button id="print">Print / PDF</button></nav>')
out.append('''<script>const slides=[...document.querySelectorAll('.slide')],notes=[...document.querySelectorAll('aside')],jump=document.querySelector('#jump');let current=0;function show(n){current=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>{s.classList.toggle('active',i===current);s.setAttribute('aria-hidden',i!==current)});notes.forEach((s,i)=>s.classList.toggle('active',i===current));document.querySelector('.count').textContent=`${current+1} / ${slides.length}`;jump.value=current;document.querySelector('#prev').disabled=current===0;document.querySelector('#next').disabled=current===slides.length-1;history.replaceState(null,'','#'+(current+1));window.scrollTo(0,0)}document.querySelector('#prev').onclick=()=>show(current-1);document.querySelector('#next').onclick=()=>show(current+1);jump.onchange=()=>show(Number(jump.value));document.querySelector('#notes').onclick=e=>{const on=document.body.classList.toggle('notes');e.currentTarget.setAttribute('aria-pressed',on)};document.querySelector('#print').onclick=()=>window.print();document.addEventListener('keydown',e=>{if(['SELECT','BUTTON','INPUT','TEXTAREA'].includes(e.target.tagName))return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(current+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(current-1)}if(e.key==='Home')show(0);if(e.key==='End')show(slides.length-1)});show(Math.max(0,(parseInt(location.hash.slice(1))||1)-1));</script></body></html>''')
(ROOT/'index.html').write_text(''.join(out))
(ROOT/'presenter-notes.md').write_text('# Jev and classifiers in agentic banking\n\n35 minutes presenting + 5 minutes discussion. Slides 24–27 are optional appendices.\n\n'+ '\n\n'.join(f'## {i+1}. {s["title"].replace("<br>"," ")}\n\n{s["notes"]}\n\n'+ '\n'.join(f'- [{sources[k][0]}]({sources[k][1]})' for k in s['refs']) for i,s in enumerate(slides)))
print(f'Built {len(slides)} slides')
